-- Buyer workspace: files (URL metadata) and one-to-many notes per property_entity.
-- If the table already existed with fewer columns, IF NOT EXISTS skips DDL; use repair migrations 0003+.
CREATE TABLE IF NOT EXISTS "panda_realty"."property_entity_files" (
  "property_entity_file_id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "property_entity_id" bigint NOT NULL REFERENCES "panda_realty"."property_entities" ("property_entity_id") ON DELETE CASCADE,
  "file_type" citext,
  "file_link" text,
  "created_at" timestamp DEFAULT now(),
  "updated_at" timestamp
);

CREATE TABLE IF NOT EXISTS "panda_realty"."property_entity_notes" (
  "property_entity_note_id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "property_entity_id" bigint NOT NULL REFERENCES "panda_realty"."property_entities" ("property_entity_id") ON DELETE CASCADE,
  "note" text NOT NULL,
  "created_by" citext,
  "created_at" timestamp DEFAULT now(),
  "updated_at" timestamp
);
